const $=s=>document.querySelector(s);$('#menu').onclick=()=>$('#menu').setAttribute('aria-expanded',$('#nav').classList.toggle('open'));document.querySelectorAll('nav a').forEach(a=>a.onclick=()=>{$('#nav').classList.remove('open');$('#menu').setAttribute('aria-expanded',false)});document.querySelectorAll('[data-social]').forEach(b=>b.onclick=()=>{$('#socialTitle').textContent=b.dataset.social+' / unavailable';$('#dialog').showModal()});$('#close').onclick=()=>$('#dialog').close();$('#resume').onclick=()=>{const u=URL.createObjectURL(new Blob(['ILLUSTRATIVE RESUME TEMPLATE\nNico Ellis — sample identity\nAdd verified biography, location, employment, portfolio evidence and public contact details.\nNo actual credentials or professional record supplied.'],{type:'text/plain'})),a=document.createElement('a');a.href=u;a.download='designer-resume-template.txt';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)};if(!matchMedia('(prefers-reduced-motion: reduce)').matches){const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('observed');observer.unobserve(e.target)}}),{threshold:.1});document.querySelectorAll('.section').forEach(x=>observer.observe(x))}